const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const ids = ['PROD-B98D14','PROD-FA0948','PROD-2DBA15','PROD-7C0240'];
ids.forEach(id => {
  const row = db.prepare('SELECT product_id, name FROM products WHERE product_id = ?').get(id);
  console.log(row.product_id, '-', row.name);
});
console.log('---');
const mouse = db.prepare(\"SELECT product_id, name FROM products WHERE name LIKE '%Wireless Mouse%'\").all();
mouse.forEach(r => console.log(r.product_id, '-', r.name));
